@tailwind base;
@tailwind components;
@tailwind utilities;

/* Semantic design tokens — HSL triplets consumed as hsl(var(--x)) via tailwind.config.js
   (bg-background, text-foreground, text-muted-foreground, bg-primary, border-border, ...).
   Berry Brook Farm uses a cream parchment base, strawberry reds, leaf greens, hay gold,
   and dark soil-brown type. Keep the NAMES — utilities depend on them. */
@layer base {
  :root {
    --font-sans: "Manrope Variable";
    --font-display: "Newsreader Variable";
    --background: 38 100% 95%;
    --foreground: 27 31% 15%;
    --card: 37 78% 91%;
    --card-foreground: 27 31% 15%;
    --popover: 38 100% 96%;
    --popover-foreground: 27 31% 15%;
    --primary: 1 57% 49%;
    --primary-foreground: 38 100% 96%;
    --secondary: 94 39% 63%;
    --secondary-foreground: 27 31% 15%;
    --muted: 31 55% 86%;
    --muted-foreground: 25 20% 39%;
    --accent: 41 74% 63%;
    --accent-foreground: 27 31% 15%;
    --destructive: 355 64% 34%;
    --destructive-foreground: 38 100% 96%;
    --border: 30 39% 76%;
    --input: 30 39% 76%;
    --ring: 1 57% 49%;
    --radius: 1.1rem;
  }

  .dark {
    --background: 27 31% 11%;
    --foreground: 38 100% 94%;
    --card: 27 28% 15%;
    --card-foreground: 38 100% 94%;
    --popover: 27 28% 15%;
    --popover-foreground: 38 100% 94%;
    --primary: 1 57% 55%;
    --primary-foreground: 38 100% 96%;
    --secondary: 105 32% 38%;
    --secondary-foreground: 38 100% 94%;
    --muted: 27 18% 22%;
    --muted-foreground: 37 24% 73%;
    --accent: 41 67% 55%;
    --accent-foreground: 27 31% 11%;
    --destructive: 355 64% 42%;
    --destructive-foreground: 38 100% 96%;
    --border: 27 19% 28%;
    --input: 27 19% 28%;
    --ring: 1 57% 55%;
  }

  * {
    @apply border-border;
  }

  html {
    scroll-behavior: smooth;
  }

  html, body {
    overflow-x: clip;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    background-image:
      linear-gradient(rgba(143, 31, 36, 0.035) 1px, transparent 1px),
      linear-gradient(90deg, rgba(143, 31, 36, 0.028) 1px, transparent 1px);
    background-size: 34px 34px;
  }

  img, video { max-width: 100%; }

  h1, h2, h3, h4 {
    @apply font-display tracking-tight;
  }

  ::selection {
    @apply bg-primary text-primary-foreground;
  }
}

@layer components {
  .farm-container {
    @apply mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8;
  }

  .painted-sign {
    @apply rounded-full border border-primary/25 bg-card px-4 py-2 text-sm font-extrabold tracking-wide text-primary shadow-sm;
    box-shadow: 0 8px 0 hsl(var(--accent) / 0.18), inset 0 0 0 1px hsl(var(--background) / 0.8);
  }

  .section-kicker {
    @apply text-xs font-black uppercase tracking-[0.22em] text-primary;
  }

  .berry-focus {
    @apply focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-background;
  }
}

