import { db } from "../lib/backend";
import { ensureVisitorSession } from "./visitorSession";

export const BOOKING_STATUS = {
  ACTIVE: "active",
  CANCELLED: "cancelled",
};

export const PICKING_SLOTS = [
  {
    id: "morning-gate",
    label: "Morning field",
    startTime: "09:00",
    endTime: "10:30",
    capacity: 24,
    availabilityTone: "plenty",
  },
  {
    id: "late-morning",
    label: "Late morning rows",
    startTime: "10:45",
    endTime: "12:15",
    capacity: 18,
    availabilityTone: "filling",
  },
  {
    id: "picnic-window",
    label: "Picnic window",
    startTime: "12:45",
    endTime: "14:15",
    capacity: 14,
    availabilityTone: "filling",
  },
  {
    id: "golden-hour",
    label: "Golden hour",
    startTime: "15:00",
    endTime: "16:30",
    capacity: 6,
    availabilityTone: "nearly-full",
  },
  {
    id: "berry-rest",
    label: "Berry rest period",
    startTime: "16:45",
    endTime: "18:15",
    capacity: 0,
    availabilityTone: "sold-out",
    unavailableReason: "This slot is full or unavailable while the field rests.",
  },
];

export function isoDateFromOffset(offsetDays = 0) {
  const date = new Date();
  date.setHours(12, 0, 0, 0);
  date.setDate(date.getDate() + offsetDays);
  return date.toISOString().slice(0, 10);
}

export function getSeededPickingDates() {
  return [0, 1, 2, 4, 5, 7].map((offset, index) => ({
    id: `harvest-day-${index + 1}`,
    date: isoDateFromOffset(offset),
    label: offset === 0 ? "Today" : offset === 1 ? "Tomorrow" : new Intl.DateTimeFormat("en", { weekday: "short", month: "short", day: "numeric" }).format(new Date(`${isoDateFromOffset(offset)}T12:00:00`)),
    status: index < 2 ? "Open today" : index < 4 ? "Limited berries" : "Weather watch",
  }));
}

const bookingEntity = () => db.entity("booking");

function normalizeRow(row) {
  if (!row) return null;
  return row.data ? { id: row.id, created_at: row.created_at, ...row.data } : row;
}

function normalizeEmail(email = "") {
  return String(email).trim().toLowerCase();
}

export function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizeEmail(email));
}

export function getSlotById(slotId) {
  return PICKING_SLOTS.find((slot) => slot.id === slotId) || null;
}

export function getDateByValue(date) {
  return getSeededPickingDates().find((item) => item.date === date) || null;
}

function activeBookingsOnly(bookings) {
  return bookings.filter((booking) => booking.status === BOOKING_STATUS.ACTIVE);
}

export function partySizeOf(booking) {
  return Number(booking.adults || 0) + Number(booking.children || 0);
}

export function makeBookingReference() {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let suffix = "";
  for (let index = 0; index < 6; index += 1) {
    suffix += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return `BBF-${suffix}`;
}

export function validatePartySize({ adults, children }) {
  const adultCount = Number(adults);
  const childCount = Number(children);
  if (!Number.isInteger(adultCount) || adultCount < 1) return "At least one adult must be included in the reservation.";
  if (!Number.isInteger(childCount) || childCount < 0) return "Children must be zero or a whole number.";
  if (adultCount + childCount > 12) return "Please call the farm for groups larger than 12 pickers.";
  return null;
}

export async function listBookingsForAvailability() {
  await ensureVisitorSession();
  const rows = await bookingEntity().list({ filters: { status: BOOKING_STATUS.ACTIVE }, limit: 500 });
  return rows.map(normalizeRow).filter(Boolean);
}

export async function calculateAvailabilityForDate(date) {
  const seededDate = getDateByValue(date);
  if (!seededDate) throw new Error("Choose one of the displayed upcoming picking dates.");

  const activeBookings = await listBookingsForAvailability();
  return PICKING_SLOTS.map((slot) => {
    const reserved = activeBookingsOnly(activeBookings)
      .filter((booking) => booking.date === date && booking.slotId === slot.id)
      .reduce((total, booking) => total + partySizeOf(booking), 0);
    const remaining = Math.max(0, slot.capacity - reserved);
    return {
      ...slot,
      date,
      reserved,
      remaining,
      available: remaining > 0,
      message: remaining > 0 ? `${remaining} picker places remaining` : (slot.unavailableReason || "This slot is full or unavailable."),
    };
  });
}

export function validateBookingInput(input = {}, slotAvailability = null) {
  const errors = {};
  const seededDate = getDateByValue(input.date);
  const slot = getSlotById(input.slotId);
  const partyError = validatePartySize({ adults: Number(input.adults), children: Number(input.children || 0) });

  if (!seededDate) errors.date = "Choose one of the displayed upcoming picking dates.";
  if (!slot) errors.slotId = "Choose an available 90-minute picking slot.";
  if (slotAvailability && !slotAvailability.available) errors.slotId = slotAvailability.message || "This slot is full or unavailable.";
  if (partyError) errors.partySize = partyError;
  if (!String(input.visitorName || "").trim()) errors.visitorName = "Enter the visitor name for the reservation.";
  if (!String(input.email || "").trim()) errors.email = "Enter an email address for booking lookup.";
  else if (!isValidEmail(input.email)) errors.email = "The email must look like an email address.";
  if (!String(input.phone || "").trim()) errors.phone = "Enter a phone number for weather or arrival updates.";
  if (input.termsAccepted !== true) errors.termsAccepted = "Accept the farm terms before reserving a slot.";

  return errors;
}

export async function createBooking(input = {}) {
  await ensureVisitorSession();
  const slot = getSlotById(input.slotId);
  const availabilityForDate = input.date ? await calculateAvailabilityForDate(input.date) : [];
  const slotAvailability = availabilityForDate.find((item) => item.id === input.slotId) || null;
  const errors = validateBookingInput(input, slotAvailability);
  if (Object.keys(errors).length > 0) {
    const error = new Error("Reservation details need attention before the booking can be created.");
    error.name = "ValidationError";
    error.fields = errors;
    throw error;
  }

  const partySize = Number(input.adults) + Number(input.children || 0);
  if (!slotAvailability || slotAvailability.remaining < partySize) {
    const error = new Error("This slot is full or unavailable for the selected party size.");
    error.name = "ValidationError";
    error.fields = { slotId: "This slot is full or unavailable for the selected party size." };
    throw error;
  }

  const booking = {
    reference: input.reference || makeBookingReference(),
    date: input.date,
    slotId: slot.id,
    slotLabel: slot.label,
    startTime: slot.startTime,
    endTime: slot.endTime,
    adults: Number(input.adults),
    children: Number(input.children || 0),
    visitorName: String(input.visitorName).trim(),
    email: normalizeEmail(input.email),
    phone: String(input.phone).trim(),
    termsAccepted: true,
    status: BOOKING_STATUS.ACTIVE,
    createdAt: new Date().toISOString(),
    cancelledAt: "",
  };

  const row = await bookingEntity().create(booking);
  return normalizeRow(row);
}

export async function lookupBooking({ reference, email } = {}) {
  await ensureVisitorSession();
  const normalizedReference = String(reference || "").trim().toUpperCase();
  const normalizedEmail = normalizeEmail(email);
  if (!normalizedReference || !normalizedEmail) {
    const error = new Error("Enter both booking reference and email to look up a reservation.");
    error.name = "ValidationError";
    error.fields = {
      ...(!normalizedReference ? { reference: "Enter the booking reference." } : {}),
      ...(!normalizedEmail ? { email: "Enter the email used for the booking." } : {}),
    };
    throw error;
  }
  if (!isValidEmail(normalizedEmail)) {
    const error = new Error("The email must look like an email address.");
    error.name = "ValidationError";
    error.fields = { email: "The email must look like an email address." };
    throw error;
  }

  const rows = await bookingEntity().list({ filters: { reference: normalizedReference, email: normalizedEmail }, limit: 10 });
  return rows.map(normalizeRow).find((booking) => booking.reference === normalizedReference && booking.email === normalizedEmail) || null;
}

export async function cancelBooking({ reference, email } = {}) {
  const booking = await lookupBooking({ reference, email });
  if (!booking) return null;
  if (booking.status === BOOKING_STATUS.CANCELLED) return booking;

  const updated = {
    reference: booking.reference,
    date: booking.date,
    slotId: booking.slotId,
    slotLabel: booking.slotLabel,
    startTime: booking.startTime,
    endTime: booking.endTime,
    adults: Number(booking.adults),
    children: Number(booking.children),
    visitorName: booking.visitorName,
    email: booking.email,
    phone: booking.phone,
    termsAccepted: booking.termsAccepted === true,
    status: BOOKING_STATUS.CANCELLED,
    createdAt: booking.createdAt,
    cancelledAt: new Date().toISOString(),
  };
  const row = await bookingEntity().update(booking.id, updated);
  return normalizeRow(row);
}

