src/data/newsletterSignup.js:
import { db } from "../lib/backend";
import { ensureVisitorSession } from "./visitorSession";
import { isValidEmail } from "./booking";

const newsletterEntity = () => db.entity("newsletterSignup");

function normalizeEmail(email = "") {
  return String(email).trim().toLowerCase();
}

function normalizeRow(row) {
  if (!row) return null;
  return row.data ? { id: row.id, created_at: row.created_at, ...row.data } : row;
}

export function validateNewsletterSignup(input = {}) {
  const email = normalizeEmail(input.email);
  if (!email) return { email: "Enter an email address for the farm noticeboard." };
  if (!isValidEmail(email)) return { email: "The email must look like an email address." };
  return {};
}

export async function createNewsletterSignup(input = {}) {
  await ensureVisitorSession();
  const errors = validateNewsletterSignup(input);
  if (Object.keys(errors).length > 0) {
    const error = new Error("Newsletter signup details need attention.");
    error.name = "ValidationError";
    error.fields = errors;
    throw error;
  }

  const row = await newsletterEntity().create({
    email: normalizeEmail(input.email),
    createdAt: new Date().toISOString(),
  });
  return normalizeRow(row);
}

